import {createReader} from './reader.js';
import {migrateTypes,usedTypes,conditionKeys,conditionCount,cleanLabel,labelKey} from './types.js';
import {makeSampleState,subjects,statusLabels,stats,overdue,dueToday,filterRecords,assertState,SAMPLE_DATE,localDate} from './data.js';
import {readStore,writeState,cacheFile} from './storage.js';

const app=document.querySelector('#app'),dialog=document.querySelector('#dialog');
const h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,cls='')=>`<i data-lucide="${name}" class="icon ${cls}" aria-hidden="true"></i>`;
const link=(label,url,cls='ghost',ico='')=>`<a class="button ${cls}" href="${h(url)}">${ico?icon(ico):''}${h(label)}</a>`;
const button=(label,action,cls='ghost',ico='',extra='')=>`<button type="button" class="button ${cls}" data-action="${action}" ${extra}>${ico?icon(ico):''}${h(label)}</button>`;
const shortDate=d=>d?d.slice(8,10)+'/'+d.slice(5,7):'Chưa đặt hạn';
const fullDate=d=>d?d.split('-').reverse().join('/'):'Chưa đặt hạn';
let state={documents:[],problems:[],notes:[]},phase='loading',loadError='',epoch=0,currentHash='',dirty=false,saveDraft=null,loadedPdf=null,loadedPdfId=null,pdfRenderTask=null,selection=null,cropBlob=null,fileChoice=null,zoom=1,notesOpen=false,focusMode=false,menuOpen=false,menuFocus=null,installEvent=null;
let urls=[],readerGeneration=0,writeQueue=Promise.resolve();const scrollPositions=new Map(),pdfCache=new Map();
const route=()=>{const [pathname,search='']=(location.hash.slice(1)||'/home').split('?');return {path:pathname,parts:pathname.split('/').filter(Boolean),params:new URLSearchParams(search)};};
const docBy=id=>state.documents.find(d=>d.id===id);
const problemBy=id=>state.problems.find(p=>p.id===id);
const activeNav=()=>route().parts[0]==='problems'?'problems':['documents','study'].includes(route().parts[0])?'documents':'home';
const pageTitle=()=>({home:'Tổng quan',documents:'Tài liệu',problems:'Problems',study:'Làm đề'}[route().parts[0]]||'Manage');
const reader=createReader({h,icon,button,link,fullDate,pill,notesForm,docBy,returnTo:()=>detailBack('documents'),getPdfModule,pdfBytes,toast,showDialog,navigate,icons,
 onBusy:busy=>app.setAttribute('aria-busy',String(busy)),
 setHash:()=>{currentHash=location.hash;},
 bindNotes:form=>{form.addEventListener('input',markDirty);saveDraft=()=>submitForm(form);},
 opened:async(id,page)=>{const d=docBy(id);if(d.lastPage!==page||!d.lastOpenedAt||d.status==='not_started')await persist(draft=>{const item=draft.documents.find(d=>d.id===id);item.lastPage=page;item.lastOpenedAt=new Date().toISOString();if(item.status==='not_started')item.status='in_progress';});},
 complete:async id=>{await persist(draft=>{const d=draft.documents.find(d=>d.id===id);d.status=d.status==='completed'?'in_progress':'completed';d.completedAt=d.status==='completed'?new Date().toISOString():null;});toast(docBy(id).status==='completed'?'Đã hoàn thành đề':'Đã mở lại đề');}
});
function icons(){window.lucide?.createIcons({attrs:{'stroke-width':1.5}});}
function announce(text){document.querySelector('#announcer').textContent=text;}
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,3800);announce(text);}
function markDirty(){dirty=true;const el=document.querySelector('[data-save-status]');if(el)el.textContent='Chưa lưu';}
function sampleNotice(records=state.documents){return records.some(r=>r.sample)?`<div class="sample-notice">${icon('info')}<span class="notice-label">Dữ liệu mẫu · Sample data</span><span>Ngày tham chiếu ${fullDate(SAMPLE_DATE)}</span></div>`:'';}
function pill(record,{includeDeadline=true}={}){let status=record.status,cls=status==='completed'||status==='mastered'?'positive':'';let label=statusLabels[status]||status;if(includeDeadline&&'dueDate'in record&&overdue(record)){cls='negative';label='Quá hạn';}else if(includeDeadline&&'dueDate'in record&&dueToday(record)){cls='warning';label='Đến hạn hôm nay';}return `<span class="pill ${cls}">${h(label)}</span>`;}
function empty(text,cta=''){return `<div class="block-empty">${h(text)}${cta}</div>`;}
function skeleton(rows=2){return Array.from({length:rows},()=>'<div class="skeleton-row"><div class="skeleton-line"></div></div>').join('');}
function blockState(content,text,rows=2){if(phase==='loading')return skeleton(rows);if(phase==='error')return `<div class="block-error"><span>Chưa đọc được dữ liệu trên thiết bị.</span>${button('Thử lại','retry')}</div>`;return content||empty(text);}
function header(title,meta='',actions='',{home=false,records=state.documents,back=null}={}){return `${back?`<div class="page-back">${link('Quay lại',back,'text','arrow-left')}</div>`:''}<header class="page-header ${route().parts[0]==='study'?'reader-header':''}"><div class="grow"><h1>${h(title)}</h1>${meta}</div>${actions?`<div class="header-actions">${actions}</div>`:''}</header>${sampleNotice(records)}`;}
function shell(content,cls=''){
 const nav=[['home','Tổng quan','layout-dashboard'],['documents','Tài liệu','files'],['problems','Problems','notebook-pen']].map(([id,label,ico])=>`<a class="nav-item" href="#/${id}" ${activeNav()===id?'aria-current="page"':''}>${icon(ico)}<span>${label}</span></a>`).join('');
 return `<aside class="sidebar" id="sidebar" aria-label="Điều hướng chính"><a class="brand" href="#/home"><svg viewBox="0 0 32 32" aria-hidden="true"><path d="M5 26V7l11 9L27 7v19M16 16v11" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg><span>Manage</span></a><p class="scope">Không gian cá nhân</p>${button('','close-menu','ghost icon-button close-menu','x','aria-label="Đóng menu"')}<p class="group-label">Học tập</p><nav>${nav}</nav><div class="sidebar-footer"><p>${icon('hard-drive')}Lưu trên thiết bị</p><p class="local-note">Một nơi cho việc học của bạn.</p><p class="online-state" id="connection">${navigator.onLine?'':'Đang ngoại tuyến'}</p>${installEvent?button('Cài Manage','install','text','download'):''}</div></aside><div class="main-plane"><div class="mobile-bar">${button('','open-menu','ghost icon-button','menu','aria-label="Mở menu" aria-controls="sidebar" aria-expanded="false"')}<span class="mobile-title">${pageTitle()}</span>${link('','#/documents/new','ghost icon-button','plus').replace('<a ','<a aria-label="Tải đề PDF" ')}</div><main class="canvas ${cls}" id="main" tabindex="-1">${content}</main></div>`;
}
const panelHead=(title,count,url)=>`<div class="panel-head"><div class="panel-heading"><h2>${title}</h2>${count!==null?`<span class="count-chip num">${count}</span>`:''}</div>${url?link('Xem tất cả',url,'text','arrow-up-right'):''}</div>`;
function problemRow(p,{home=false}={}){const d=docBy(p.documentId);return `<article class="feed-row" data-record-id="${p.id}"><a href="#/problems/${p.id}" class="row-main"><img class="crop-thumb" src="${h(p.imageUrl||'')}" ${p.imageKey?`data-image-key="${h(p.imageKey)}"`:''} alt="Câu ${h(p.title)}"><span class="grow"><span class="row-title">${h(p.title)}</span><span class="source-label">${h(d?.title||'Không còn đề nguồn')} · Trang ${p.sourcePage}</span>${!home?`<span class="row-sub">${h(p.subject)} · ${typeMarkup(p)}<span class="inline-status"> · ${h(statusLabels[p.status])}</span>${p.sample?' · Mẫu':''}</span>`:''}</span></a><div class="row-end">${home?'':pill(p)}<a class="button ghost icon-button" href="#/study/${h(p.documentId)}?page=${p.sourcePage}" aria-label="Mở đề nguồn ${h(d?.title)}, trang ${p.sourcePage}">${icon('arrow-up-right')}</a></div></article>`;}
function homeView(){
 const s=stats(state),attention=state.documents.filter(d=>overdue(d)||dueToday(d)).sort((a,b)=>a.dueDate.localeCompare(b.dueDate));
 const recent=state.documents.filter(d=>d.lastOpenedAt&&d.status!=='completed').sort((a,b)=>b.lastOpenedAt.localeCompare(a.lastOpenedAt))[0];
 const next=attention[0]||recent;let finding='Bắt đầu buổi học với một đề PDF.';
 if(s.overdue)finding=`${new Set(attention.filter(overdue).map(d=>d.subject)).size===1?attention[0].subject:'Bạn'} còn ${s.overdue} đề quá hạn.`;else if(s.today)finding=`Hôm nay còn ${s.today} đề đến hạn.`;else if(recent)finding=`Tiếp tục đề ${recent.title}.`;
 const date=state.documents.some(d=>d.sample)?SAMPLE_DATE:localDate();
 const heading=header('Chào bạn, đây là Manage.',`<p class="date-line">${h(new Intl.DateTimeFormat('vi-VN',{weekday:'long',day:'2-digit',month:'long',year:'numeric'}).format(new Date(date+'T12:00:00')))}</p><div class="finding">${phase==='loading'?'<div class="skeleton-line"></div>':`<p>${phase==='error'?'Chưa đọc được hạn đề.':h(finding)}</p>`}${next&&phase==='ready'?link(overdue(next)?`Làm đề ${next.subject}`:'Tiếp tục',`#/study/${next.id}`,'text','arrow-up-right'):''}</div>`,link('Tải đề PDF','#/documents/new','primary','plus'),{home:true});
 const tiles=[['Quá hạn',s.overdue,'đề','Cần hoàn thành','/documents?deadline=overdue'],['Đến hạn hôm nay',s.today,'đề','Trước cuối ngày','/documents?deadline=today'],['Đang làm',s.doing,'đề','Tiếp tục phiên học','/documents?status=in_progress'],['Cần ôn',s.review,'câu','Trong sổ Problems','/problems?status=review']].map(([label,n,unit,caption,url])=>`<a href="#${url}" class="count-tile"><span class="count-label">${label}</span>${phase==='loading'?'<div class="skeleton-value"></div>':`<span class="count-value num">${phase==='error'?'?':n}<small>${unit}</small></span>`}<span class="count-caption">${phase==='error'?'Chưa đọc được dữ liệu':caption}</span></a>`).join('');
 const deadlines=attention.slice(0,2).map(d=>`<article class="feed-row"><a href="#/study/${d.id}" class="row-main"><span class="grow"><span class="row-title">${h(d.title)}</span><span class="row-sub">${h(d.subject)} · Hạn ${shortDate(d.dueDate)}</span></span></a><div class="row-end">${pill(d)}${link('Mở đề',`#/study/${d.id}`,'text','arrow-up-right')}</div></article>`).join('');
 const n=recent&&state.notes.find(n=>n.documentId===recent.id);
 const resume=recent?`<h3>${h(recent.title)}</h3><span class="row-sub">${h(recent.subject)} · Trang <span class="num">${recent.lastPage}/${recent.pageCount}</span></span><p class="resume-note">${h(n?.strategy||'Tiếp tục từ trang đang đọc.')}</p>${link('Tiếp tục',`#/study/${recent.id}?page=${recent.lastPage}`,'ghost','arrow-right')}`:empty('Chưa có phiên học',link('Mở tài liệu','#/documents','text'));
 const review=state.problems.filter(p=>p.status==='review');const homeProblems=[...review.filter(p=>['P1','P3'].includes(p.id)),...review.filter(p=>!['P1','P3'].includes(p.id))].slice(0,2).map(p=>problemRow(p,{home:true})).join('');
 const notes=state.notes.filter(n=>n.strategy||n.traps||n.method).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).slice(0,2).map(n=>`<article class="feed-row notes-row"><a class="row-main" href="#/study/${n.documentId}?notes=open"><span class="grow"><span class="row-title">${h(docBy(n.documentId)?.title)}</span><span class="row-sub">${h(n.strategy||n.traps||n.method)}</span></span>${icon('arrow-up-right')}</a></article>`).join('');
 return heading+`<div class="home-grid"><section class="panel home-panel span-3 resume">${panelHead('Tiếp tục học',null,null)}${blockState(resume,'Chưa có phiên học.')}</section><section class="count-grid" aria-label="Việc học">${tiles}</section><section class="panel home-panel span-9 home-deadlines">${panelHead('Hạn gần nhất',phase==='ready'?attention.length:null,'#/documents?deadline=attention')}<div class="feed">${blockState(deadlines,'Không có đề đến hạn.')}</div></section><section class="panel home-panel span-6 home-problems">${panelHead('Câu cần ôn',phase==='ready'?review.length:null,'#/problems?status=review')}<div class="feed">${blockState(homeProblems,'Chưa có câu cần ôn.')}</div></section><section class="panel home-panel span-6 home-notes">${panelHead('Ghi chú gần đây',null,null)}<div class="feed">${blockState(notes,'Chưa có ghi chú.')}</div></section></div>`;
}
function options(items,value,all){return (all===null?'':`<option value="">${all}</option>`)+items.map(([v,t])=>`<option value="${h(v)}" ${value===v?'selected':''}>${h(t)}</option>`).join('');}
const compactFilters=matchMedia('(max-width:1100px)');
const listSources={documents:'#/documents',problems:'#/problems'},detailSources=new Map();
let editorDraft=null;
const returnTo=kind=>listSources[kind]||`#/${kind}`;
const detailBack=kind=>detailSources.get(route().path)||returnTo(kind);
const typeText=r=>(r.typeIds||[]).map(id=>state.types?.find(t=>t.id===id)?.label).filter(Boolean);
function typeMarkup(r){return `<span class="type-labels">${(r.typeIds||[]).length?(r.typeIds||[]).map(id=>`<span class="${route().params.get('type')===id?'type-match':''}">${h(state.types?.find(t=>t.id===id)?.label||'Chưa phân loại')}</span>`).join(' · '):'Chưa phân loại'}</span>`;}
function filterField(label,name,values,selected,emptyLabel){return `<label class="filter-field"><span>${label}</span><select class="control" name="${name}" aria-label="${label}" ${phase!=='ready'?'disabled':''}>${options(values,selected,emptyLabel)}</select></label>`;}
function filterFields(params,problems){const types=usedTypes(state,problems,params.get('subject')||'');return filterField('Môn học','subject',subjects.map(s=>[s,s]),params.get('subject'),'Tất cả môn')+filterField('Dạng bài','type',[...types.map(t=>[t.id,t.label]),['unclassified','Chưa phân loại']],params.get('type'),'Tất cả dạng bài')+filterField(problems?'Trạng thái ôn':'Trạng thái','status',(problems?['review','mastered']:['not_started','in_progress','completed']).map(s=>[s,statusLabels[s]]),params.get('status'),'Mọi trạng thái')+(problems?'':filterField('Hạn chót','deadline',[['overdue','Quá hạn'],['today','Hôm nay'],['attention','Cần chú ý']],params.get('deadline'),'Mọi hạn chót'));}
function filterToolbar(problems){const {params}=route(),count=conditionCount(params,problems);return `<form class="study-toolbar" id="filters" role="search"><div class="search-line"><div class="search-field">${icon('search')}<input class="control" name="q" type="search" value="${h(params.get('q')||'')}" placeholder="${problems?'Tìm câu hỏi':'Tìm tên đề'}" aria-label="${problems?'Tìm câu hỏi':'Tìm tên đề'}" autocomplete="off"></div>${compactFilters.matches?button(`Bộ lọc${count?' ('+count+')':''}`,'filters','secondary','sliders-horizontal','aria-haspopup="dialog" aria-expanded="false" aria-controls="dialog"'):''}</div><div class="filter-line">${compactFilters.matches?'':`<div class="inline-filters">${filterFields(params,problems)}</div>`}<div class="sort-field">${filterField('Sắp xếp','sort',problems?[['recent','Gần đây'],['title','Tên câu']]:[['deadline','Hạn gần nhất'],['title','Tên đề'],['recent','Mở gần đây']],params.get('sort')||(problems?'recent':'deadline'),null)}</div></div></form>`;}
function appliedFilters(problems){const {params}=route();const names={subject:'Môn học',type:'Dạng bài',status:'Trạng thái',deadline:'Hạn chót'},deadlines={overdue:'Quá hạn',today:'Hôm nay',attention:'Cần chú ý'};const chips=conditionKeys(problems).filter(k=>params.get(k)).map(k=>{const v=params.get(k),label=k==='type'?(v==='unclassified'?'Chưa phân loại':state.types?.find(t=>t.id===v)?.label||v):k==='status'?statusLabels[v]:k==='deadline'?deadlines[v]:v;return button(`${names[k]}: ${label}`,'remove-filter','secondary','x',`data-key="${k}" aria-label="Bỏ điều kiện ${names[k]}: ${h(label)}"`);});return chips.length?`<div class="applied-filters" aria-label="Đang lọc">${chips.join('')}${button('Xóa tất cả bộ lọc','clear-filters','text')}</div>`:'';}
function listView(problems=false){const all=problems?state.problems:state.documents,rows=filterRecords(all,route().params,{problems});const finding=phase==='loading'?'<span class="skeleton-line finding-skeleton"></span>':phase==='error'?'<p class="muted">Chưa đọc được dữ liệu.</p>':`<p class="muted finding">${problems?(rows.length?`${rows.filter(p=>p.status==='review').length} câu cần ôn trong ${rows.length} câu.`:all.length?'0 câu phù hợp.':'Chưa có câu hỏi.'):(rows.length?`${rows.length} đề · ${rows.filter(d=>(d.typeIds||[]).length).length} đề đã gắn dạng bài.`:all.length?'0 đề phù hợp.':'Chưa có đề PDF.')}</p>`;return header(problems?'Problems':'Tài liệu',finding,problems?'':link('Tải đề PDF','#/documents/new','primary','plus'),{records:all})+`<div id="toolbar-slot">${filterToolbar(problems)}</div><div id="applied-slot">${appliedFilters(problems)}</div><div id="list-content">${listContent(problems)}</div>`;}
function documentDeadline(d,compact=false){const warning=overdue(d)?'Quá hạn':dueToday(d)?'Đến hạn hôm nay':'';return `<span class="document-deadline"><span>${h(compact?shortDate(d.dueDate):d.dueDate||'Chưa đặt hạn')}</span>${warning?`<span class="deadline-notice ${overdue(d)?'is-overdue':'is-today'}">${h(warning)}</span>`:''}</span>`;}
function documentRow(d,{showSampleLabel=false}={}){return `<tr data-record-id="${d.id}"><td class="identity"><a href="#/study/${d.id}"><img class="media" src="${h(d.previewUrl||'')}" ${d.previewKey?`data-image-key="${h(d.previewKey)}"`:''} alt="Trang đầu ${h(d.title)}"><span class="grow"><span class="row-title">${h(d.title)}</span><span class="document-subject row-sub">${h(d.subject)}</span>${typeMarkup(d)}${showSampleLabel&&d.sample?'<span class="row-sub document-sample">Tài liệu mẫu</span>':''}<span class="mobile-meta row-sub"><span>${h(d.subject)} · ${d.pageCount} trang · ${h(statusLabels[d.status])}</span>${documentDeadline(d,true)}</span></span></a></td><td class="subject-column muted">${h(d.subject)}</td><td class="numeric pages-column">${d.pageCount} trang</td><td class="numeric deadline-column muted">${documentDeadline(d)}</td><td class="status-column">${pill(d,{includeDeadline:false})}</td><td class="doc-menu">${button('','document-menu','ghost icon-button','ellipsis',`data-id="${d.id}" aria-label="Thao tác với ${h(d.title)}"`)}</td></tr>`;}
function listContent(problems){const {params}=route(),all=problems?state.problems:state.documents,rows=filterRecords(all,params,{problems}),pageSize=6,total=rows.length,pages=Math.max(1,Math.ceil(total/pageSize)),page=Math.min(pages,Math.max(1,Number(params.get('p'))||1)),shown=rows.slice((page-1)*pageSize,page*pageSize);let content;if(params.has('p')&&Number(params.get('p'))!==page){params.set('p',page);history.replaceState(null,'',`#${route().path}?${params}`);currentHash=location.hash;}
 if(problems)content=shown.map(p=>problemRow(p)).join('');else content=shown.map(d=>documentRow(d,{showSampleLabel:!all.every(r=>r.sample)})).join('');
 const clear=button('Xóa tất cả bộ lọc','clear-filters','text');
 let body=blockState(content,all.length?'Không có kết quả phù hợp.':problems?'Cắt câu hỏi từ một đề để bắt đầu.':'Thêm đề PDF để bắt đầu.',6);
 if(phase==='ready'&&!rows.length)body=empty(all.length?'Không có kết quả phù hợp.':problems?'Cắt câu hỏi từ một đề để bắt đầu.':'Thêm đề PDF để bắt đầu.',all.length?clear:link(problems?'Mở tài liệu':'Tải đề PDF',problems?'#/documents':'#/documents/new','text'));
 if(!problems&&shown.length&&phase==='ready')body=`<div class="table-wrap"><table class="table"><thead><tr><th class="identity" scope="col">Tên đề</th><th class="subject-column" scope="col">Môn học</th><th class="numeric pages-column" scope="col">Trang</th><th class="numeric deadline-column" scope="col">Hạn chót</th><th class="status-column" scope="col">Trạng thái</th><th scope="col"><span class="sr-only">Thao tác</span></th></tr></thead><tbody>${content}</tbody></table></div>`;
 return `<div class="list-caption"><span class="num" aria-live="polite">${phase==='loading'?'Đang tải':phase==='error'?'Chưa đọc được':total} ${problems?'câu':'đề'}${problems?` · ${rows.filter(p=>p.status==='review').length} cần ôn`:''}</span></div><div class="${problems?'problem-list':''}">${body}</div>${total?`<div class="range-footer"><span class="num">${(page-1)*pageSize+1}–${Math.min(page*pageSize,total)} / ${total} ${problems?'câu':'đề'}</span>${pages>1?`<div>${button('Trước','list-prev','ghost','chevron-left',page===1?'disabled':'')}${button('Sau','list-next','ghost','chevron-right',page===pages?'disabled':'')}</div>`:''}</div>`:''}`;
}
const field=(label,name,value='',type='text',extra='')=>`<div class="field"><label for="${name}">${label}</label><input class="control" id="${name}" name="${name}" type="${type}" value="${h(value)}" ${extra}></div>`;
const area=(label,name,value='',extra='')=>`<div class="field"><label for="${name}">${label}</label><textarea class="control" id="${name}" name="${name}" ${extra}>${h(value)}</textarea></div>`;
function documentForm(id){const d=id&&docBy(id);if(id&&!d)return notFound('Không tìm thấy đề');return header(d?'Chỉnh sửa đề':'Nạp đề','', '',{records:[],back:returnTo('documents')})+`<section class="panel form-panel"><form id="document-form" class="form-stack" data-id="${h(id||'')}">${d?'':`<div class="dropzone" id="dropzone">${icon('file-up')}<span>Chọn PDF hoặc kéo tệp vào đây</span><span class="small muted">Tên đề, môn học và hạn chót ở cùng một nơi.</span><input type="file" id="pdf-file" name="pdf" accept="application/pdf,.pdf" aria-label="Chọn PDF" required></div><div class="file-summary" id="file-summary" aria-live="polite"></div>`}${field('Tên đề','title',d?.title||'','text','required maxlength="160"')}<div class="field-row"><div class="field"><label for="subject">Môn học</label><select class="control" id="subject" name="subject" required>${options(subjects.map(s=>[s,s]),d?.subject,'Chọn môn học')}</select></div>${field('Hạn chót','dueDate',d?.dueDate||localDate(),'date')}</div>${typeEditor(d?.subject||'',d?.typeIds||[])}<p class="small muted">Bỏ trống hạn chót nếu chưa có lịch làm đề.</p><div class="error-message" id="form-error" role="alert"></div><div class="form-actions"><button class="button primary" type="submit">${icon('check')}Lưu đề</button>${link('Hủy',returnTo('documents'),'ghost')}</div><p class="save-status" data-save-status></p></form></section>`;}
function notesForm(d){const n=state.notes.find(n=>n.documentId===d.id);return `<aside class="notes-panel"><div class="panel-head"><h2>Ghi chú</h2>${button('','notes','ghost icon-button','x','aria-label="Đóng ghi chú"')}</div><form id="notes-form" class="form-stack" data-id="${d.id}">${area('Chiến thuật','strategy',n?.strategy)}${area('Bẫy đề','traps',n?.traps)}${area('Cách giải','method',n?.method)}<div class="error-message" id="notes-error" role="alert"></div><div class="form-actions"><button type="submit" class="button primary">Lưu ghi chú</button></div><p class="save-status" data-save-status aria-live="polite"></p></form></aside>`;}
function readerView(id,capture=false){const d=docBy(id);if(!d)return notFound('Không tìm thấy đề');const {params}=route();const page=Math.max(1,Math.min(d.pageCount,Number(params.get('page'))||d.lastPage||1));notesOpen=params.get('notes')==='open';const meta=`<div class="reader-document-meta"><span>${h(d.subject)}</span><span>Hạn ${fullDate(d.dueDate)}</span>${pill(d)}</div>`;
 const actions=capture?link('Hủy',`#/study/${d.id}?page=${page}`,'ghost','x'):`${button(d.status==='completed'?'Làm tiếp':'Hoàn thành đề','complete','ghost',d.status==='completed'?'rotate-ccw':'check',`data-id="${d.id}"`)}${button('Ghi chú','notes','ghost','panel-right',`aria-expanded="${notesOpen}"`)}${button('','fullscreen','ghost icon-button',focusMode?'minimize':'maximize','aria-label="Bật hoặc tắt toàn màn hình"')}`;
 return header(capture?'Cắt câu hỏi':d.title,meta,actions,{records:[d],back:capture?null:detailBack('documents')})+`<div class="work-grid ${!notesOpen&&!capture?'notes-closed':''} ${notesOpen&&!capture?'mobile-notes-open':''}" id="work-grid"><section class="reader-column" aria-label="Trang PDF"><div class="reader-tools">${button('','previous-page','ghost icon-button','chevron-left',`aria-label="Trang trước" ${page===1?'disabled':''}`)}<input class="control page-number num" id="page-number" type="number" min="1" max="${d.pageCount}" value="${page}" aria-label="Số trang"><span class="reader-page-count num">/ ${d.pageCount} trang</span>${button('','next-page','ghost icon-button','chevron-right',`aria-label="Trang sau" ${page===d.pageCount?'disabled':''}`)}<span class="grow"></span><select class="control" id="zoom" aria-label="Thu phóng">${[[1,'Vừa chiều rộng'],[1.25,'125%'],[1.5,'150%'],[2,'200%']].map(([v,t])=>`<option value="${v}" ${zoom===v?'selected':''}>${t}</option>`).join('')}</select>${capture?'':link('Cắt câu hỏi',`#/study/${d.id}/crop?page=${page}`,'ghost','scan-line')}</div><div class="reader-viewport" id="reader-viewport" aria-busy="true"><div class="skeleton-row"><div class="skeleton-line"></div></div><p class="small muted">Đang mở PDF…</p></div>${capture?`<p class="capture-help">Kéo để chọn vùng. Có thể nhập vị trí và kích thước theo phần trăm.</p><div class="coordinate-fields">${field('Trái (%)','crop-x','8','number','min="0" max="99" step="1"')}${field('Trên (%)','crop-y','19','number','min="0" max="99" step="1"')}${field('Rộng (%)','crop-w','84','number','min="1" max="100" step="1"')}${field('Cao (%)','crop-h','22','number','min="1" max="100" step="1"')}</div><div class="form-actions">${button('Chọn theo tọa độ','apply-crop','ghost','crop')}${button('Tiếp tục','crop-next','primary','arrow-right','disabled')}</div>`:''}</section>${capture?captureForm(d,page):notesOpen?notesForm(d):''}</div>`;}
function captureForm(d,page){return `<aside class="notes-panel capture-form"><div class="panel-head"><h2>Phân tích câu hỏi</h2>${button('Chọn lại vùng','reset-crop','text','crop')}</div><div id="crop-preview">${empty('Chưa chọn vùng câu hỏi.')}</div><p class="source-label">${h(d.title)} · Trang ${page}</p><form id="capture-form" class="form-stack" data-id="${d.id}" data-page="${page}">${field('Tên câu hỏi','title','','text','required maxlength="160"')}${typeEditor(d.subject,[])}${area('Lý do sai','reason')}${area('Bẫy đề','trap')}${area('Cách giải','method')}<p class="small muted">Môn học: ${h(d.subject)}</p><div id="capture-error" class="error-message" role="alert"></div><div class="form-actions"><button class="button primary" type="submit" id="save-crop" disabled>Lưu vào Problems</button></div><p class="save-status" data-save-status></p></form></aside>`;}
function problemDetail(id){const p=problemBy(id);if(!p)return notFound('Không tìm thấy câu');const d=docBy(p.documentId);return header(p.title,'','',{records:[p],back:detailBack('problems')})+`<div class="work-grid"><section class="problem-visual"><div class="detail-state">${pill(p)}${button(p.status==='review'?'Đã nắm vững':'Cần ôn lại','review-status','ghost',p.status==='review'?'check':'rotate-ccw',`data-id="${p.id}"`)}</div><a class="source-link source-label" href="#/study/${p.documentId}?page=${p.sourcePage}">${h(d?.title)} · Trang ${p.sourcePage}${icon('arrow-up-right')}</a><img class="problem-image" src="${h(p.imageUrl||'')}" ${p.imageKey?`data-image-key="${h(p.imageKey)}"`:''} alt="${h(p.title)}"><div class="destructive">${button('Xóa câu','delete-problem','ghost danger','trash-2',`data-id="${p.id}"`)}</div></section><aside class="notes-panel detail-form"><div class="panel-head"><h2>Phân tích lỗi</h2></div><form id="problem-form" class="form-stack" data-id="${p.id}">${field('Tên câu hỏi','title',p.title,'text','required maxlength="160"')}${typeEditor(p.subject,p.typeIds||[])}${area('Lý do sai','reason',p.reason)}${area('Bẫy đề','trap',p.trap)}${area('Cách giải','method',p.method)}<div class="error-message" id="problem-error" role="alert"></div><button type="submit" class="button primary">Lưu phân tích</button><p class="save-status" data-save-status aria-live="polite"></p></form></aside></div>`;}
function notFound(title='Không tìm thấy'){return header(title,'','',{records:[]})+empty('Nội dung này không còn trong không gian học.',link('Về Tổng quan','#/home','text'));}

async function render(){reader.destroy();const token=++epoch;closeMenu(false);dirty=false;saveDraft=null;fileChoice=null;selection=null;cropBlob=null;for(const u of urls)URL.revokeObjectURL(u);urls=[];pdfRenderTask?.cancel();pdfRenderTask=null;document.body.classList.remove('capture-ready');const r=route();currentHash=location.hash||'#/home';const [view,id,sub]=r.parts;let content,cls='';
 if(view==='home'){content=homeView();cls='home';}else if(view==='documents'&&(id==='new'||sub==='edit'))content=documentForm(id==='new'?null:id);else if(view==='documents'&&!id){content=listView();cls='list-view';}else if(view==='problems'&&id)content=problemDetail(id);else if(view==='problems'){content=listView(true);cls='list-view';}else if(view==='study'){if(sub==='crop'){content=readerView(id,true);cls='study';}else{cls='study reader-screen';content=docBy(id)?reader.html(docBy(id)):header(phase==='loading'?'Tài liệu':state.documents.length?'Không tìm thấy đề':'Chưa có đề PDF','','',{records:[]})+blockState('', 'Mở một đề để bắt đầu đọc.')+link('Tải đề PDF','#/documents/new','primary');}}else content=notFound();
 app.innerHTML=shell(content,cls);app.setAttribute('aria-busy',String(phase==='loading'));icons();document.title=`${app.querySelector('h1')?.textContent||'Manage'} · Manage`;document.body.classList.toggle('focus-mode',focusMode&&view==='study');hydrateImages();attachForms();window.scrollTo(0,scrollPositions.get(currentHash)||0);
 if(view==='study'&&docBy(id)&&phase==='ready'){if(sub==='crop')await loadReader(token,true);else reader.mount();}
}
async function hydrateImages(){for(const img of app.querySelectorAll('img')){img.onerror=()=>{if(img.dataset.imageKey&&!img.dataset.hydrated)return;img.hidden=true;if(img.nextElementSibling?.dataset.imageFallback)return;const message=document.createElement('span');message.className='small muted';message.dataset.imageFallback='true';message.innerHTML=`Ảnh chưa tải được ${button('Thử lại','retry-image','text')}`;img.after(message);};img.onload=()=>{img.hidden=false;if(img.nextElementSibling?.dataset.imageFallback)img.nextElementSibling.remove();};if(img.dataset.imageKey){try{const blob=await readStore('files',img.dataset.imageKey);img.dataset.hydrated='true';if(blob&&img.isConnected){const u=URL.createObjectURL(blob);urls.push(u);img.src=u;}else if(img.isConnected)img.onerror();}catch{img.dataset.hydrated='true';img.onerror();}}}}
async function getPdfModule(){if(!getPdfModule.promise)getPdfModule.promise=import('/vendor/pdf.mjs').then(m=>{m.GlobalWorkerOptions.workerSrc='/vendor/pdf.worker.mjs';return m;});return getPdfModule.promise;}
async function pdfBytes(d){let blob=await readStore('files',`pdf:${d.id}`);if(!blob){if(!d.pdfUrl)throw new Error('Không còn tệp PDF trên thiết bị.');const response=await fetch(d.pdfUrl);if(!response.ok)throw new Error('Chưa tải được PDF.');blob=await response.blob();try{await cacheFile(`pdf:${d.id}`,blob);}catch{toast('PDF đã mở, nhưng chưa lưu được bản dùng ngoại tuyến.');}}return new Uint8Array(await blob.arrayBuffer());}
async function loadReader(token,capture){const generation=++readerGeneration;const current=()=>token===epoch&&generation===readerGeneration;const d=docBy(route().parts[1]);const viewport=document.querySelector('#reader-viewport');if(!d||!viewport)return;pdfRenderTask?.cancel();viewport.setAttribute('aria-busy','true');try{
 const m=await getPdfModule();if(!current())return;if(!pdfCache.has(d.id))pdfCache.set(d.id,(async()=>m.getDocument({data:await pdfBytes(d),useSystemFonts:true,isEvalSupported:false}).promise)().catch(error=>{pdfCache.delete(d.id);throw error;}));
 const pdf=await pdfCache.get(d.id);if(!current())return;loadedPdf=pdf;loadedPdfId=d.id;const pageNo=Math.min(pdf.numPages,Math.max(1,Number(document.querySelector('#page-number').value)));const page=await pdf.getPage(pageNo);if(!current())return;
 const base=page.getViewport({scale:1});const available=Math.max(240,viewport.clientWidth-(innerWidth<701?24:40));const scale=(available/base.width)*zoom;const cssViewport=page.getViewport({scale});const ratio=Math.max(2,window.devicePixelRatio||1);const canvas=document.createElement('canvas');canvas.width=Math.floor(cssViewport.width*ratio);canvas.height=Math.floor(cssViewport.height*ratio);canvas.style.width=`${cssViewport.width}px`;canvas.style.height=`${cssViewport.height}px`;canvas.setAttribute('aria-label',`${d.title}, trang ${pageNo}`);const stage=document.createElement('div');stage.className='pdf-stage';stage.append(canvas);viewport.replaceChildren(stage);
 pdfRenderTask=page.render({canvasContext:canvas.getContext('2d'),viewport:cssViewport,transform:[ratio,0,0,ratio,0,0]});await pdfRenderTask.promise;if(!current())return;viewport.setAttribute('aria-busy','false');
 if(capture){const layer=document.createElement('div');layer.className='capture-layer';layer.setAttribute('aria-label','Chọn vùng câu hỏi bằng kéo hoặc tọa độ bên dưới');layer.innerHTML='<div class="crop-selection" hidden></div>';stage.append(layer);bindCrop(layer,canvas);}
 if(d.lastPage!==pageNo||!d.lastOpenedAt||d.status==='not_started'){await persist(draft=>{const item=draft.documents.find(x=>x.id===d.id);item.lastPage=pageNo;item.lastOpenedAt=new Date().toISOString();if(item.status==='not_started')item.status='in_progress';});}
 }catch(error){if(!current()||error?.name==='RenderingCancelledException')return;loadedPdfId=null;viewport.innerHTML=`<div class="block-error"><span>${h(error.message||'Chưa mở được PDF.')}</span>${button('Thử lại','retry-pdf','ghost','rotate-cw')}</div>`;viewport.setAttribute('aria-busy','false');icons();}}
function bindCrop(layer,canvas){let start=null;const pos=e=>{const b=layer.getBoundingClientRect();return {x:Math.max(0,Math.min(1,(e.clientX-b.left)/b.width)),y:Math.max(0,Math.min(1,(e.clientY-b.top)/b.height))};};layer.addEventListener('pointerdown',e=>{start=pos(e);layer.setPointerCapture(e.pointerId);selection={x:start.x,y:start.y,width:0,height:0};drawSelection();});layer.addEventListener('pointermove',e=>{if(!start)return;const p=pos(e);selection={x:Math.min(p.x,start.x),y:Math.min(p.y,start.y),width:Math.abs(p.x-start.x),height:Math.abs(p.y-start.y)};drawSelection();});layer.addEventListener('pointerup',async()=>{start=null;if(selection&&selection.width>.005&&selection.height>.005){await makeCrop(canvas);markDirty();}else selection=null;});layer.addEventListener('pointercancel',()=>{start=null;});}
function drawSelection(){const el=document.querySelector('.crop-selection');if(!el||!selection)return;el.hidden=false;Object.assign(el.style,{left:`${selection.x*100}%`,top:`${selection.y*100}%`,width:`${selection.width*100}%`,height:`${selection.height*100}%`});for(const [key,val]of [['x',selection.x],['y',selection.y],['w',selection.width],['h',selection.height]]){const input=document.querySelector(`#crop-${key}`);if(input&&document.activeElement!==input)input.value=(val*100).toFixed(1);}}
async function makeCrop(source=document.querySelector('.pdf-stage canvas')){if(!source||!selection)return;const c=document.createElement('canvas');c.width=Math.max(1,Math.round(selection.width*source.width));c.height=Math.max(1,Math.round(selection.height*source.height));c.getContext('2d').drawImage(source,selection.x*source.width,selection.y*source.height,selection.width*source.width,selection.height*source.height,0,0,c.width,c.height);cropBlob=await new Promise(resolve=>c.toBlob(resolve,'image/png'));if(!cropBlob)throw new Error('Chưa tạo được ảnh câu hỏi.');const u=URL.createObjectURL(cropBlob);urls.push(u);document.querySelector('#crop-preview').innerHTML=`<img class="crop-preview" src="${u}" alt="Xem trước vùng câu hỏi vừa chọn">`;document.querySelector('#save-crop').disabled=false;document.querySelector('[data-action="crop-next"]').disabled=false;}

function persist(change,options={}){const operation=writeQueue.then(async()=>{const next=structuredClone(state);change(next);assertState(next);await writeState(next,options);state=next;return next;});writeQueue=operation.catch(()=>{});return operation;}
function attachForms(){for(const form of app.querySelectorAll('form:not(#filters)'))form.addEventListener('input',markDirty);const form=app.querySelector('#notes-form')||app.querySelector('#problem-form')||app.querySelector('#document-form')||app.querySelector('#capture-form');if(form)saveDraft=()=>submitForm(form);bindFilters();bindTypeEditor(form);
 const input=app.querySelector('#pdf-file');if(input){input.addEventListener('change',()=>chooseFile(input.files[0]));const zone=app.querySelector('#dropzone');zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('dragging');});zone.addEventListener('dragleave',()=>zone.classList.remove('dragging'));zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('dragging');chooseFile(e.dataTransfer.files[0]);});}
 app.querySelector('#page-number')?.addEventListener('change',e=>changePage(Number(e.target.value)));app.querySelector('#zoom')?.addEventListener('change',async e=>{zoom=Number(e.target.value);selection=null;cropBlob=null;await loadReader(epoch,route().parts[2]==='crop');});
}
function updateFilters(data){const r=route(),params=new URLSearchParams(r.params),problems=r.parts[0]==='problems';for(const [key,value]of data){if(value)params.set(key,value);else params.delete(key);}params.delete('p');if(data.has('subject')&&params.get('type')&&params.get('type')!=='unclassified'&&!usedTypes(state,problems,params.get('subject')||'').some(t=>t.id===params.get('type'))){params.delete('type');toast('Dạng bài đã được bỏ');}if(problems)params.delete('deadline');history.replaceState(null,'',`#${r.path}${params.size?'?'+params:''}`);currentHash=location.hash;const el=document.querySelector('#list-content'),oldPositions=new Map([...el.querySelectorAll('[data-record-id]')].map(x=>[x.dataset.recordId,x.getBoundingClientRect().top]));el.innerHTML=listContent(problems);document.querySelector('#applied-slot').innerHTML=appliedFilters(problems);const finding=document.querySelector('.finding');if(finding){const rows=filterRecords(problems?state.problems:state.documents,params,{problems});finding.textContent=problems?`${rows.filter(p=>p.status==='review').length} câu cần ôn trong ${rows.length} câu.`:`${rows.length} đề · ${rows.filter(d=>(d.typeIds||[]).length).length} đề đã gắn dạng bài.`;}if(data.has('subject')){const type=document.querySelector('#filters [name=type]');if(type)type.innerHTML=options([...usedTypes(state,problems,params.get('subject')||'').map(t=>[t.id,t.label]),['unclassified','Chưa phân loại']],params.get('type'),'Tất cả dạng bài');}const trigger=document.querySelector('[data-action=filters]');if(trigger)trigger.innerHTML=icon('sliders-horizontal')+`Bộ lọc${conditionCount(params,problems)?' ('+conditionCount(params,problems)+')':''}`;icons();hydrateImages();if(!matchMedia('(prefers-reduced-motion: reduce)').matches)for(const row of el.querySelectorAll('[data-record-id]')){const old=oldPositions.get(row.dataset.recordId);if(old!==undefined){const diff=old-row.getBoundingClientRect().top;if(diff)row.animate([{transform:`translateY(${diff}px)`},{transform:'translateY(0)'}],{duration:180,easing:'cubic-bezier(0.22,1,0.36,1)'});}}announce(el.querySelector('.list-caption')?.textContent||'Đã lọc');}
function bindFilters(){const filters=app.querySelector('#filters');if(!filters)return;filters.addEventListener('submit',e=>e.preventDefault());filters.addEventListener('input',e=>{if(e.target.name==='q')updateFilters(new Map([['q',e.target.value]]));});filters.addEventListener('change',e=>updateFilters(new Map([[e.target.name,e.target.value]])));}

async function chooseFile(file){fileChoice=null;const summary=document.querySelector('#file-summary');if(!file)return;summary.textContent='Đang đọc PDF…';try{if(!file.size)throw new Error('Tệp đang trống. Chọn PDF khác.');const bytes=new Uint8Array(await file.arrayBuffer());if(new TextDecoder().decode(bytes.slice(0,5))!=='%PDF-')throw new Error('Tệp này không phải PDF hợp lệ.');const m=await getPdfModule();const pdf=await m.getDocument({data:bytes,useSystemFonts:true,isEvalSupported:false}).promise;if(!pdf.numPages)throw new Error('PDF không có trang.');const p=await pdf.getPage(1),v=p.getViewport({scale:1});const canvas=document.createElement('canvas');canvas.width=v.width;canvas.height=v.height;await p.render({canvasContext:canvas.getContext('2d'),viewport:v}).promise;const preview=await new Promise(resolve=>canvas.toBlob(resolve));fileChoice={file,pageCount:pdf.numPages,preview};await pdf.destroy();summary.textContent=`${file.name} · ${fileChoice.pageCount} trang · ${(file.size/1024/1024).toLocaleString('vi-VN',{maximumFractionDigits:1})} MB`;const name=document.querySelector('#title');if(!name.value)name.value=file.name.replace(/\.pdf$/i,'');document.querySelector('#pdf-file').required=false;document.querySelector('#form-error').textContent='';markDirty();}catch(error){summary.textContent='';document.querySelector('#form-error').textContent=error.message||'Không đọc được tệp PDF.';}}
function typeEditor(subject,ids){editorDraft={subject,ids:[...ids],types:structuredClone(state.types||[])};return `<section class="type-editor" aria-label="Dạng bài"><h2>Dạng bài</h2><div id="type-editor-body"></div></section>`;}
function renderTypeEditor(){const box=document.querySelector('#type-editor-body');if(!box||!editorDraft)return;const {subject,ids,types}=editorDraft,invalid=ids.filter(id=>types.find(t=>t.id===id)?.subject!==subject);box.innerHTML=`<div class="selected-types">${ids.length?ids.map(id=>{const t=types.find(t=>t.id===id);return button(`${t?.label||id}${invalid.includes(id)?' (khác môn)':''}`,'remove-type','secondary','x',`data-type-id="${h(id)}" aria-label="Bỏ dạng bài ${h(t?.label||id)}"`);}).join(''):'<p class="small muted">Chưa phân loại</p>'}</div>${invalid.length?'<p class="error-message" role="alert">Môn học đã đổi. Bỏ các nhãn khác môn trước khi lưu.</p>':''}<label class="field"><span>Chọn dạng bài</span><select class="control" id="choose-type" ${subject?'':'disabled'} aria-label="Chọn dạng bài"><option value="">${subject?'Chọn nhãn đã lưu':'Chọn môn học trước'}</option>${types.filter(t=>t.subject===subject&&!ids.includes(t.id)).sort((a,b)=>a.label.localeCompare(b.label,'vi')).map(t=>`<option value="${h(t.id)}">${h(t.label)}</option>`).join('')}</select></label><label class="field"><span>Thêm dạng bài</span><input class="control" id="new-type" maxlength="80" aria-label="Tên dạng bài mới" ${subject?'':'disabled'}></label>${button('Thêm dạng bài','add-type','secondary','plus',subject?'':'disabled')}<p class="small muted">Nhãn được lưu cùng nội dung. Có thể chọn nhiều dạng bài.</p><p id="type-error" class="error-message" role="alert"></p>`;icons();}
function bindTypeEditor(form){if(!form?.querySelector('.type-editor'))return;renderTypeEditor();form.querySelector('[name=subject]')?.addEventListener('change',e=>{editorDraft.subject=e.target.value;renderTypeEditor();markDirty();});form.addEventListener('change',e=>{if(e.target.id==='choose-type'&&e.target.value){editorDraft.ids.push(e.target.value);renderTypeEditor();document.querySelector('#choose-type').focus();markDirty();}});form.addEventListener('keydown',e=>{if(e.target.id==='new-type'&&e.key==='Enter'){e.preventDefault();addType();}});}
function addType(){const input=document.querySelector('#new-type'),label=cleanLabel(input.value);if(!label){document.querySelector('#type-error').textContent='Nhập tên dạng bài.';input.focus();return;}const existing=editorDraft.types.find(t=>t.subject===editorDraft.subject&&labelKey(t.label)===labelKey(label));const type=existing||{id:crypto.randomUUID(),subject:editorDraft.subject,label};if(!existing)editorDraft.types.push(type);if(!editorDraft.ids.includes(type.id))editorDraft.ids.push(type.id);renderTypeEditor();document.querySelector('#new-type').focus();markDirty();}
function commitTypes(draft,record){if(!editorDraft)return;if(editorDraft.ids.some(id=>editorDraft.types.find(t=>t.id===id)?.subject!==editorDraft.subject))throw new Error('Bỏ các dạng bài khác môn trước khi lưu.');draft.types??=[];record.typeIds=editorDraft.ids.map(id=>{const type=editorDraft.types.find(t=>t.id===id);const existing=draft.types.find(t=>t.subject===type.subject&&labelKey(t.label)===labelKey(type.label));if(existing)return existing.id;draft.types.push({...type});return type.id;});record.typeIds=[...new Set(record.typeIds)];}
async function submitForm(form){if(!form.reportValidity())return false;const data=new FormData(form),id=form.dataset.id,submit=form.querySelector('[type=submit]');submit.disabled=true;form.inert=true;form.setAttribute('aria-busy','true');const errorEl=form.querySelector(':scope > [role=alert]'),stamp=form.querySelector('[data-save-status]');if(errorEl)errorEl.textContent='';if(stamp)stamp.textContent='Đang lưu…';try{
 if(data.has('title')&&!String(data.get('title')).trim())throw new Error('Nhập tên trước khi lưu.');
 if(form.id==='document-form'){const existing=docBy(id);if(!existing&&!fileChoice)throw new Error('Chọn một PDF hợp lệ trước khi lưu.');const docId=existing?.id||crypto.randomUUID();const files=existing?[]:[[`pdf:${docId}`,fileChoice.file],[`preview:${docId}`,fileChoice.preview]];await persist(draft=>{if(existing){Object.assign(draft.documents.find(d=>d.id===docId),{title:data.get('title').trim(),subject:data.get('subject'),dueDate:data.get('dueDate')});}else draft.documents.push({id:docId,title:data.get('title').trim(),subject:data.get('subject'),dueDate:data.get('dueDate'),pageCount:fileChoice.pageCount,status:'not_started',lastPage:1,createdAt:new Date().toISOString(),lastOpenedAt:null,completedAt:null,sample:false,previewKey:`preview:${docId}`});commitTypes(draft,draft.documents.find(d=>d.id===docId));},{files});dirty=false;toast('Đã lưu đề trên thiết bị');navigate(returnTo('documents'));return true;
 }else if(form.id==='notes-form'){await persist(draft=>{let n=draft.notes.find(n=>n.documentId===id);if(!n){n={documentId:id};draft.notes.push(n);}Object.assign(n,{strategy:data.get('strategy').trim(),traps:data.get('traps').trim(),method:data.get('method').trim(),updatedAt:new Date().toISOString()});});
 }else if(form.id==='problem-form'){await persist(draft=>{Object.assign(draft.problems.find(p=>p.id===id),{title:data.get('title').trim(),reason:data.get('reason').trim(),trap:data.get('trap').trim(),method:data.get('method').trim(),updatedAt:new Date().toISOString()});commitTypes(draft,draft.problems.find(p=>p.id===id));});document.querySelector('h1').textContent=data.get('title').trim();
 }else if(form.id==='capture-form'){if(!cropBlob||!selection)throw new Error('Chọn vùng câu hỏi trước khi lưu.');const pId=crypto.randomUUID(),d=docBy(id);await persist(draft=>{draft.problems.unshift({id:pId,title:data.get('title').trim(),documentId:id,sourcePage:Number(form.dataset.page),subject:d.subject,reason:data.get('reason').trim(),trap:data.get('trap').trim(),method:data.get('method').trim(),status:'review',sample:Boolean(d.sample),imageKey:`crop:${pId}`,cropRect:selection,updatedAt:new Date().toISOString()});commitTypes(draft,draft.problems.find(p=>p.id===pId));},{files:[[`crop:${pId}`,cropBlob]]});dirty=false;toast('Đã lưu câu vào Problems');navigate(`#/problems/${pId}`);return true;}
 dirty=false;if(stamp)stamp.textContent='Đã lưu trên thiết bị';announce('Đã lưu');return true;
 }catch(error){if(errorEl)errorEl.textContent=error.name==='QuotaExceededError'?'Thiết bị đã hết dung lượng. Giải phóng dung lượng rồi thử lại.':error.message||'Chưa lưu được. Thử lại.';if(stamp)stamp.textContent='Chưa lưu';return false;}finally{submit.disabled=false;form.inert=false;form.setAttribute('aria-busy','false');}}

function showDialog(title,body,choices){return new Promise(resolve=>{const previous=document.activeElement;dialog.innerHTML=`<h2 id="dialog-title">${h(title)}</h2>${body}<div class="dialog-actions">${choices.map(c=>button(c.label,`dialog:${c.value}`,c.primary?'primary':c.danger?'ghost danger':'ghost')).join('')}</div>`;dialog.showModal();icons();dialog.querySelector('button')?.focus();const finish=value=>{dialog.close();dialog.removeEventListener('click',click);dialog.removeEventListener('cancel',cancel);setTimeout(()=>{if(previous?.isConnected)previous.focus();},0);resolve(value);};const click=e=>{const b=e.target.closest('[data-action^="dialog:"]');if(b)finish(b.dataset.action.slice(7));};const cancel=e=>{e.preventDefault();finish('cancel');};dialog.addEventListener('click',click);dialog.addEventListener('cancel',cancel);});}
async function canLeave(){if(!dirty)return true;const result=await showDialog('Lưu thay đổi?',`<p>Bản nháp chưa được lưu trên thiết bị.</p>`,[{label:'Ở lại',value:'cancel'},{label:'Bỏ thay đổi',value:'discard'},{label:'Lưu',value:'save',primary:true}]);if(result==='cancel')return false;if(result==='save'){if(!saveDraft||!await saveDraft())return false;}dirty=false;return true;}
async function navigate(hash){if(hash===location.hash){closeMenu();return;}if(!await canLeave())return;const r=route();if(['documents','problems'].includes(r.parts[0])&&r.parts.length===1)listSources[r.parts[0]]=location.hash;if((r.parts.length===1&&['documents','problems'].includes(r.parts[0]))||(r.parts[0]==='problems'&&hash.startsWith('#/study/')))detailSources.set(hash.slice(1).split('?')[0],location.hash);scrollPositions.set(currentHash,scrollY);closeMenu(false);location.hash=hash;}
function openMenu(){menuOpen=true;menuFocus=document.querySelector('[data-action=open-menu]');const sidebar=document.querySelector('#sidebar');sidebar.classList.add('open');sidebar.setAttribute('role','dialog');sidebar.setAttribute('aria-modal','true');document.querySelector('.main-plane').inert=true;document.querySelector('[data-action=open-menu]').setAttribute('aria-expanded','true');sidebar.querySelector('.close-menu').focus();}
function closeMenu(returnFocus=true){if(!menuOpen)return;menuOpen=false;const sidebar=document.querySelector('#sidebar');sidebar?.classList.remove('open');sidebar?.removeAttribute('role');sidebar?.removeAttribute('aria-modal');const plane=document.querySelector('.main-plane');if(plane)plane.inert=false;document.querySelector('[data-action=open-menu]')?.setAttribute('aria-expanded','false');if(returnFocus&&menuFocus?.isConnected)menuFocus.focus();}
async function changePage(page){const d=docBy(route().parts[1]);if(!Number.isInteger(page)||page<1||page>d.pageCount){document.querySelector('#page-number').value=d.lastPage;toast('Số trang nằm ngoài tài liệu.');return;}const p=route().params;p.set('page',page);await navigate(`#${route().path}?${p}`);}
async function openFilters(){if(!compactFilters.matches)return;const r=route(),problems=r.parts[0]==='problems',draft=new URLSearchParams(r.params),trigger=document.querySelector('[data-action=filters]');trigger?.setAttribute('aria-expanded','true');dialog.classList.add('filter-dialog');const promise=showDialog('Bộ lọc',`<form id="dialog-filters" class="form-stack">${filterFields(draft,problems)}${button('Xóa tất cả bộ lọc','clear-draft','text')}</form>`,[{label:'Hủy',value:'cancel'},{label:'Áp dụng',value:'apply',primary:true}]);if(!matchMedia('(prefers-reduced-motion: reduce)').matches)dialog.animate([{transform:'translateY(8px)'},{transform:'translateY(0)'}],{duration:180,easing:'cubic-bezier(0.22,1,0.36,1)'});const form=dialog.querySelector('form');form.addEventListener('submit',e=>e.preventDefault());form.addEventListener('change',e=>{draft.set(e.target.name,e.target.value);if(e.target.name==='subject'){if(draft.get('type')!=='unclassified'&&!usedTypes(state,problems,draft.get('subject')).some(t=>t.id===draft.get('type')))draft.delete('type');form.querySelector('[name=type]').innerHTML=options([...usedTypes(state,problems,draft.get('subject')).map(t=>[t.id,t.label]),['unclassified','Chưa phân loại']],draft.get('type'),'Tất cả dạng bài');}});form.querySelector('[data-action=clear-draft]').onclick=()=>{for(const key of conditionKeys(problems)){draft.delete(key);form.elements.namedItem(key).value='';}form.querySelector('[name=type]').innerHTML=options([...usedTypes(state,problems).map(t=>[t.id,t.label]),['unclassified','Chưa phân loại']],'','Tất cả dạng bài');};const result=await promise;if(result==='apply')updateFilters(new Map(conditionKeys(problems).map(k=>[k,draft.get(k)||''])));dialog.innerHTML='';dialog.classList.remove('filter-dialog');trigger?.setAttribute('aria-expanded','false');setTimeout(()=>{if(trigger?.isConnected)trigger.focus();},0);}


async function deleteProblem(id){const p=problemBy(id);const answer=await showDialog('Xóa câu hỏi?',`<p>${h(p.title)} sẽ bị xóa cùng phân tích lỗi.</p>`,[{label:'Hủy',value:'cancel'},{label:'Xóa câu',value:'delete',danger:true}]);if(answer!=='delete')return;await persist(draft=>draft.problems=draft.problems.filter(x=>x.id!==id),{deleteFiles:p.imageKey?[p.imageKey]:[]});dirty=false;toast('Đã xóa câu');navigate('#/problems');}
async function documentMenu(id){const d=docBy(id);const action=await showDialog(d.title,`<p>${h(d.subject)} · ${d.pageCount} trang · Hạn ${fullDate(d.dueDate)}</p>`,[{label:'Đóng',value:'cancel'},{label:'Chỉnh sửa',value:'edit'},{label:'Xóa đề',value:'delete',danger:true}]);if(action==='edit')navigate(`#/documents/${id}/edit`);else if(action==='delete'){const related=state.problems.filter(p=>p.documentId===id);const ok=await showDialog('Xóa đề?',`<p>${h(d.title)} sẽ bị xóa${related.length?` cùng ${related.length} câu trong Problems`:''} và ghi chú của đề.</p>`,[{label:'Hủy',value:'cancel'},{label:related.length?'Xóa đề và câu liên quan':'Xóa đề',value:'delete',danger:true}]);if(ok==='delete'){await persist(draft=>{draft.documents=draft.documents.filter(d=>d.id!==id);draft.problems=draft.problems.filter(p=>p.documentId!==id);draft.notes=draft.notes.filter(n=>n.documentId!==id);},{deleteFiles:[`pdf:${id}`,`preview:${id}`,...related.map(p=>p.imageKey).filter(Boolean)]});toast('Đã xóa đề');render();}}}
async function action(name,b){const r=route(),id=b?.dataset.id||r.parts[1];switch(name){
 case'retry':await initialize();break;
 case'retry-image':for(const img of app.querySelectorAll('img'))if(img.hidden&&!img.dataset.imageKey){img.hidden=false;const original=img.src;img.removeAttribute('src');img.src=original;}await hydrateImages();break;
 case'open-menu':openMenu();break;case'close-menu':closeMenu();break;
 case'filters':await openFilters();break;
 case'add-type':addType();break;
 case'remove-type':editorDraft.ids=editorDraft.ids.filter(id=>id!==b.dataset.typeId);renderTypeEditor();document.querySelector('#choose-type')?.focus();markDirty();break;
 case'clear-filters':updateFilters(new Map(conditionKeys(r.parts[0]==='problems').map(k=>[k,''])));document.querySelector('#filters input')?.focus();break;
 case'remove-filter':updateFilters(new Map([[b.dataset.key,'']]));document.querySelector('#applied-slot button, #filters input')?.focus();break;
 case'list-prev':case'list-next':{const p=Number(r.params.get('p'))||1;r.params.set('p',p+(name==='list-next'?1:-1));navigate(`#${r.path}?${r.params}`);break;}
 case'document-menu':await documentMenu(id);break;
 case'delete-problem':await deleteProblem(id);break;
 case'complete':await persist(draft=>{const d=draft.documents.find(d=>d.id===id);d.status=d.status==='completed'?'in_progress':'completed';d.completedAt=d.status==='completed'?new Date().toISOString():null;});toast(docBy(id).status==='completed'?'Đã hoàn thành đề':'Đã mở lại đề');if(!dirty)render();else {const meta=document.querySelector('.reader-document-meta .pill');if(meta)meta.outerHTML=pill(docBy(id));b.innerHTML=docBy(id).status==='completed'?'Làm tiếp':'Hoàn thành đề';}break;
 case'review-status':await persist(draft=>{const p=draft.problems.find(p=>p.id===id);p.status=p.status==='review'?'mastered':'review';p.updatedAt=new Date().toISOString();});toast(statusLabels[problemBy(id).status]);if(!dirty)render();else {const status=document.querySelector('.detail-state .pill');status.outerHTML=pill(problemBy(id));b.textContent=problemBy(id).status==='review'?'Đã nắm vững':'Cần ôn lại';}break;
 case'notes':if(await canLeave()){notesOpen=!notesOpen;const params=r.params;if(notesOpen)params.set('notes','open');else params.delete('notes');history.replaceState(null,'',`#${r.path}${params.size?'?'+params:''}`);render();}break;
 case'fullscreen':focusMode=!focusMode;document.body.classList.toggle('focus-mode',focusMode);if(focusMode){try{await document.documentElement.requestFullscreen();}catch{}}else if(document.fullscreenElement)await document.exitFullscreen();if(!dirty)render();break;
 case'previous-page':await changePage(Number(document.querySelector('#page-number').value)-1);break;
 case'next-page':await changePage(Number(document.querySelector('#page-number').value)+1);break;
 case'retry-pdf':await loadReader(epoch,r.parts[2]==='crop');break;
 case'apply-crop':{const value=k=>Number(document.querySelector(`#crop-${k}`).value)/100;const x=value('x'),y=value('y'),width=value('w'),height=value('h');if([x,y,width,height].some(n=>!Number.isFinite(n))||x<0||y<0||width<=0||height<=0||x+width>1.001||y+height>1.001){toast('Vùng chọn phải nằm trong trang PDF.');break;}selection={x,y,width,height};drawSelection();await makeCrop();markDirty();break;}
 case'crop-next':document.body.classList.add('capture-ready');document.querySelector('#title')?.focus();break;
 case'reset-crop':document.body.classList.remove('capture-ready');selection=null;cropBlob=null;document.querySelector('.crop-selection')?.setAttribute('hidden','');document.querySelector('#crop-preview').innerHTML=empty('Chưa chọn vùng câu hỏi.');document.querySelector('#save-crop').disabled=true;document.querySelector('[data-action=crop-next]').disabled=true;document.querySelector('[data-action=apply-crop]')?.focus();break;
 case'install':if(installEvent){await installEvent.prompt();await installEvent.userChoice;installEvent=null;b.hidden=true;}break;
}}
app.addEventListener('click',async e=>{const anchor=e.target.closest('a[href^="#/"]');if(anchor&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey){e.preventDefault();await navigate(anchor.getAttribute('href'));return;}const b=e.target.closest('[data-action]');if(b&&!b.disabled){const wasDisabled=b.disabled;b.disabled=true;try{await action(b.dataset.action,b);}catch(error){toast(error.message||'Chưa thực hiện được. Thử lại.');}finally{if(b.isConnected)b.disabled=wasDisabled;}}});
app.addEventListener('submit',e=>{e.preventDefault();if(e.target.id!=='filters')submitForm(e.target);});
window.addEventListener('hashchange',async()=>{const next=location.hash;if(reader.isActive()&&route().path===currentHash.slice(1).split('?')[0]){currentHash=next;reader.syncRoute();return;}if(dirty){history.replaceState(null,'',currentHash);if(!await canLeave())return;history.replaceState(null,'',next);}scrollPositions.set(currentHash,scrollY);await render();});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&dialog.open){e.preventDefault();dialog.dispatchEvent(new Event('cancel',{cancelable:true}));return;}if(e.key==='Escape'){if(menuOpen){e.preventDefault();closeMenu();}else if(focusMode&&!document.fullscreenElement){focusMode=false;document.body.classList.remove('focus-mode');if(!dirty)render();}}if(menuOpen&&e.key==='Tab'){const items=[...document.querySelector('#sidebar').querySelectorAll('a,button:not([disabled])')].filter(x=>x.getClientRects().length),first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement&&focusMode){focusMode=false;document.body.classList.remove('focus-mode');if(!dirty)render();}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;if(!dirty)render();});
for(const event of ['online','offline'])window.addEventListener(event,()=>{const el=document.querySelector('#connection');if(el)el.textContent=navigator.onLine?'':'Đang ngoại tuyến';});
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(route().parts[0]==='study'&&route().parts[2]==='crop'&&loadedPdf&&!dirty)loadReader(epoch,route().parts[2]==='crop');},200);});
async function initialize(){phase='loading';render();try{const saved=await readStore('state','main');if(saved&&!['documents','problems','notes'].every(k=>Array.isArray(saved[k])))throw new Error('Dữ liệu trên thiết bị chưa đọc được.');const before=JSON.stringify(saved);state=migrateTypes(saved||makeSampleState());if(defaultReader){const d=state.documents.find(d=>d.id==='D1')||[...state.documents].sort((a,b)=>(b.lastOpenedAt||'').localeCompare(a.lastOpenedAt||''))[0];history.replaceState(null,'',d?`#/study/${d.id}?page=${d.lastPage||1}`:'#/study');}if(!saved||JSON.stringify(state)!==before)await writeState(state);assertState(state);phase='ready';loadError='';}catch(error){phase='error';loadError=error.message;}await render();}
const defaultReader=!location.hash;if(defaultReader)history.replaceState(null,'','#/study');
await initialize();
if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
// Read-only diagnostics for verification, kept out of the product flow.
window.__manage={getState:()=>structuredClone(state),stats:()=>stats(state),getPhase:()=>({phase,error:loadError}),getSelection:()=>selection&&{...selection},getReader:()=>reader.snapshot()};

compactFilters.addEventListener('change',()=>{if(dialog.open&&dialog.classList.contains('filter-dialog'))dialog.dispatchEvent(new Event('cancel',{cancelable:true}));if(document.querySelector('#toolbar-slot')){const focusInside=document.activeElement?.closest('#toolbar-slot, #dialog');document.querySelector('#toolbar-slot').innerHTML=filterToolbar(route().parts[0]==='problems');bindFilters();icons();if(focusInside)document.querySelector('#filters [name=subject], #filters [data-action=filters]')?.focus();}});


document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!dialog.open&&!menuOpen&&reader.escape()){e.preventDefault();e.stopImmediatePropagation();}},true);
